window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[121]={"id":"121","numero":121,"titre":"Handicap psychique","objectifs":[{"id":"121-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","contenu":"<div class=\"notion-course\"><h4>Décrire un retentissement, pas seulement un diagnostic</h4><p>Le handicap psychique correspond aux limitations d’activité et aux restrictions de participation liées à un trouble psychiatrique, en interaction avec l’environnement. Les troubles cognitifs, les symptômes, la motivation et les difficultés relationnelles peuvent y contribuer. Un diagnostic psychiatrique ne suffit pas à déterminer l’autonomie ou les besoins de compensation.</p><table><thead><tr><th>Repère</th><th>Handicap intellectuel</th><th>Handicap psychique</th></tr></thead><tbody><tr><td>Origine</td><td>Trouble du développement intellectuel : limitations des fonctions intellectuelles et du fonctionnement adaptatif.</td><td>Conséquences fonctionnelles d’un trouble psychiatrique ; capacités intellectuelles globales parfois préservées.</td></tr><tr><td>Début</td><td>Pendant la période développementale ; pas nécessairement identifié à la naissance.</td><td>À tout âge selon le trouble, souvent à l’<span class=\"nc-pink nc-bold\">adolescence</span> ou à l’<span class=\"nc-pink nc-bold\">âge adulte</span>.</td></tr><tr><td>Évolution</td><td>Besoins variables avec les apprentissages, les soutiens et les comorbidités.</td><td>Souvent fluctuante ; décalage possible entre amélioration symptomatique et récupération fonctionnelle.</td></tr><tr><td>Soins</td><td>Suivi somatique et psychique adapté, rééducation et accompagnement.</td><td>Soins psychiatriques et somatiques, réhabilitation et accompagnement social.</td></tr></tbody></table><ul><li>Les deux situations peuvent coexister.</li><li>Évaluer le fonctionnement réel et les ressources de la personne ; ne pas déduire ses capacités d’une étiquette.</li><li>L’estimation historique de 700 000 personnes citée dans le cours est un ordre de grandeur ancien, non une prévalence nationale actualisée.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181fab965de12d7387f1c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Handicap psychique (121)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p>Correction des équivalences « intellectuel = dès la naissance / stable / peu de soins ».</p></details><details data-lisa-review=\"20261014\"><summary>Situations de départ LiSA vérifiées</summary><p>Attendus consultés sur LiSA 2026 le 14 octobre 2026, reformulés pour la révision.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_et_traitement_de_fond_d%27un_patient_souffrant_d%27un_trouble_psychiatrique_chronique_(hors_d%C3%A9pression)_SDD-269\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 269 · Suivi et traitement de fond d’un trouble psychiatrique chronique hors dépression</a><ul><li>Réévaluer décompensation, risque suicidaire, comorbidités, autonomie et insertion ; surveiller les psychotropes et leur observance.</li><li>Expliquer les psychothérapies et coordonner les soins ; la valorisation du stage inclut réhabilitation, remédiation cognitive et démarches MDPH.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Situation_de_handicap_SDD-345\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 345 · Situation de handicap</a><ul><li>Évaluer limitations d’activité, restrictions de participation, besoins de réadaptation et aides humaines ou matérielles.</li><li>Informer la personne et ses aidants, apprécier leur retentissement et orienter vers la MDPH ; intégrer les ressources du milieu de vie.</li></ul></li></ul><p>Les liens ciblent les compétences pertinentes pour cet item ; ils ne signifient pas que la fiche couvre à elle seule toute la situation de départ.</p></details>","frequence":0},{"id":"121-2","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<div class=\"notion-course\"><h4>Évaluation globale et projet de rétablissement</h4><p>Avec la personne, identifier ce qu’elle souhaite retrouver : logement, liens sociaux, formation, emploi, autonomie. Le rétablissement ne se réduit pas à l’absence de symptômes.</p><table><thead><tr><th>Domaine</th><th>Exemples à évaluer</th></tr></thead><tbody><tr><td>Déficiences</td><td>Symptômes, cognition, sommeil, effets indésirables, santé somatique et addictions.</td></tr><tr><td>Activités</td><td>Se laver, cuisiner, gérer les médicaments, un budget, un rendez-vous ou un transport.</td></tr><tr><td>Participation</td><td>Vie familiale, <span class=\"nc-pink nc-bold\">sociale</span>, citoyenne, études et travail.</td></tr><tr><td>Environnement</td><td>Soutiens, logement, accessibilité, ressources, stigmatisation et obstacles.</td></tr></tbody></table><ul><li>Associer soins et accompagnement, avec un référent et un suivi coordonné. Évaluer les risques suicidaires, la vulnérabilité et les besoins des aidants.</li><li>CMP, hôpital de jour, CATTP et équipes de réhabilitation selon le besoin.</li><li>SAVS : accompagnement de la vie <span class=\"nc-pink nc-bold\">sociale</span> ; SAMSAH : accompagnement incluant des soins et une coordination médicale/paramédicale.</li><li>Logement ordinaire avec soutien, résidence accueil ou établissement adapté selon autonomie et souhaits ; pas de bascule automatique à 60 ans.</li><li>L’<span class=\"nc-pink nc-bold\">entreprise adaptée</span> appartient au milieu ordinaire ; l’<span class=\"nc-pink nc-bold\">ESAT</span> relève du secteur médico-social. Une RQTH ne vaut pas à elle seule orientation en <span class=\"nc-pink nc-bold\">ESAT</span>.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181fab965de12d7387f1c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Handicap psychique (121)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"121-3","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge psychothérapeutique","contenu":"<div class=\"notion-course\"><h4>Soins ciblés et transfert dans la vie quotidienne</h4><ul><li>Psychoéducation / <span class=\"nc-green_bg\">éducation thérapeutique</span> : connaissance du trouble, signes précoces, plan de crise, traitements et prévention des rechutes. Associer les proches avec l’accord de la personne.</li><li>TCC et entraînement aux habiletés sociales : objectifs concrets, mises en situation et soutien à l’utilisation quotidienne.</li><li><span class=\"nc-green_bg\">Remédiation cognitive</span> après évaluation individualisée : entraînement ou compensation des fonctions altérées, avec un projet fonctionnel choisi.</li><li>Adapter les psychotropes pour stabiliser le trouble et limiter sédation, effets moteurs et métaboliques qui aggravent le handicap.</li><li>ECT et rTMS répondent à des indications du trouble sous-jacent ; elles ne constituent pas un traitement systématique du handicap psychique.</li><li>Évaluer les résultats sur le quotidien, la qualité de vie et les objectifs de la personne, au-delà des scores aux tests.</li></ul><div class=\"callout\"><p>La restructuration cognitive travaille les pensées et interprétations ; la <span class=\"nc-green_bg\">remédiation cognitive</span> entraîne ou compense des fonctions cognitives.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181fab965de12d7387f1c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Handicap psychique (121)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"121-4","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la réhabilitation psychosociale","contenu":"<div class=\"notion-course\"><h4>Réhabilitation psychosociale</h4><p>Ensemble coordonné de soins et d’actions d’accompagnement favorisant le pouvoir d’agir, les compétences et la participation <span class=\"nc-pink nc-bold\">sociale</span>. Le projet est coconstruit ; la personne n’a pas à attendre une disparition complète des symptômes pour être accompagnée.</p><table><thead><tr><th>Besoin</th><th>Leviers</th></tr></thead><tbody><tr><td>Logement</td><td>Accès et maintien au logement, SAVS/SAMSAH, résidences accueil, solutions médico-sociales selon besoins.</td></tr><tr><td>Études et emploi</td><td>Aménagements, RQTH, accompagnement vers l’emploi, Cap emploi ; <span class=\"nc-pink nc-bold\">entreprise adaptée</span> ou <span class=\"nc-pink nc-bold\">ESAT</span> selon évaluation et orientation.</td></tr><tr><td>Ressources</td><td>Évaluer droits sociaux, assurance maladie, <span class=\"nc-yellow_bg\">pension d’invalidité</span> et <span class=\"nc-yellow_bg\">AAH</span> ; accompagner le dossier <span class=\"nc-pink nc-bold\">MDPH</span>.</td></tr><tr><td>Vie <span class=\"nc-pink nc-bold\">sociale</span></td><td>GEM, associations, activités choisies, pair-aidance et lutte contre l’isolement.</td></tr></tbody></table><ul><li>La MDPH évalue les besoins ; la CDAPH statue notamment sur des droits et orientations. Le versement de l’AAH relève de la Caf ou MSA sous conditions.</li><li>La <span class=\"nc-yellow_bg\">pension d’invalidité</span> dépend des critères de l’assurance maladie ; avoir travaillé ne suffit pas à l’obtenir.</li><li>Une <span class=\"nc-yellow_bg\">AAH</span> différentielle peut compléter une pension insuffisante sous conditions : « déjà travaillé = pas d’<span class=\"nc-yellow_bg\">AAH</span> » est faux.</li><li>Ne pas imposer un délai universel de six mois après un AVC pour toute décision d’invalidité.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181fab965de12d7387f1c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Handicap psychique (121)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.ameli.fr/assure/droits-demarches/invalidite-handicap/handicap\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Invalidité et handicap, AAH différentielle</a></li></ul><p>Correction du cumul AAH/invalidité, du milieu ordinaire/protégé et des seuils d’âge présentés comme automatiques.</p></details>","frequence":2},{"id":"121-5","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge judiciaire","contenu":"<div class=\"notion-course\"><h4>Protection juridique : nécessité, subsidiarité et proportionnalité</h4><p>Le handicap ne justifie pas automatiquement une mesure. Rechercher une altération médicalement constatée des facultés empêchant la personne de pourvoir seule à ses intérêts ; choisir l’aide la moins contraignante adaptée, en préservant son autonomie.</p><table><thead><tr><th>Mesure</th><th>Principe</th></tr></thead><tbody><tr><td>Sauvegarde de justice</td><td>Protection temporaire ; la personne conserve en principe sa capacité, avec actes confiés à un mandataire spécial si nécessaire.</td></tr><tr><td>Curatelle</td><td>Assistance ou contrôle pour les actes importants ; degré adapté à la situation.</td></tr><tr><td>Tutelle</td><td>Représentation pour les actes prévus par la mesure lorsque l’assistance est insuffisante.</td></tr></tbody></table><ul><li>Requête au juge des contentieux de la protection du tribunal judiciaire du lieu de résidence, par une personne habilitée ou le procureur. Le médecin n’est pas l’unique initiateur.</li><li>Certificat médical circonstancié d’un médecin inscrit sur la liste du procureur pour une demande judiciaire ; modalités particulières pour la sauvegarde par déclaration médicale.</li><li>Distinguer protection de la personne et du patrimoine, soins sans consentement et capacité à consentir à un acte médical.</li><li>Informer la personne, rechercher sa volonté et réévaluer la mesure ; tutelle ne signifie pas suppression de tous les droits.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/1cb37f85d94181fab965de12d7387f1c?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Handicap psychique (121)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.service-public.fr/particuliers/vosdroits/R50473\" target=\"_blank\" rel=\"noopener noreferrer\">Service public · Protection juridique d’un majeur</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Diagnostic et handicap","contenu":"<div class=\"notion-course\"><p>Évaluer le fonctionnement réel, pas seulement la maladie.</p></div>"},{"type":"piege","titre":"AAH","contenu":"<div class=\"notion-course\"><p>Avoir travaillé ou percevoir une pension n’exclut pas automatiquement l’<span class=\"nc-yellow_bg\">AAH</span>.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Décrire déficiences, activités, participation et environnement.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Projet partagé de rétablissement, soins et accompagnement.</li><li>Vérifier droits et protection juridique proportionnée.</li></ul></div>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Décompensation ou risque immédiat ?","detail":"<ul><li>Évaluer sécurité, symptômes, santé somatique et besoins essentiels.</li></ul>","branches":[{"label":"Oui","to":"soins"},{"label":"Non / état stabilisé","to":"besoins"}]},{"id":"soins","kind":"urgent","label":"Organiser les soins nécessaires puis réévaluer l’autonomie","detail":"<ul><li>Un handicap durable et une urgence clinique appellent des réponses complémentaires.</li></ul>","branches":[]},{"id":"besoins","kind":"decision","label":"Quels obstacles, ressources et souhaits ?","detail":"<ul><li>Activités, participation, cognition, logement, liens sociaux, études et travail.</li><li>Distinguer handicap psychique et intellectuel sans les rendre incompatibles.</li></ul>","branches":[{"label":"Projet partagé","to":"rehabilitation"}]},{"id":"rehabilitation","kind":"decision","label":"Associer soins et réhabilitation psychosociale","detail":"<ul><li>Psychoéducation, psychothérapie, remédiation et entraînement des habiletés selon besoin.</li><li>Coordination avec personne, proches avec accord, équipes sanitaires et sociales.</li></ul>","branches":[{"label":"Aides et aménagements","to":"aides"},{"label":"Difficulté de protection des intérêts","to":"protection"}]},{"id":"aides","kind":"finish","label":"Mobiliser les dispositifs adaptés au fonctionnement","detail":"<ul><li>MDPH, droits/ressources, logement, accompagnement et emploi selon évaluation.</li><li>Distinguer ESAT, entreprise adaptée et milieu ordinaire ; aides non automatiques.</li></ul>","branches":[]},{"id":"protection","kind":"decision","label":"Une mesure moins contraignante suffit-elle ?","detail":"<ul><li>Capacités et besoins concrets ; nécessité, subsidiarité et proportionnalité.</li><li>Le diagnostic psychiatrique seul ne suffit pas à justifier une mesure judiciaire.</li></ul>","branches":[{"label":"Oui","to":"soutien"},{"label":"Non, altération justifiant une protection","to":"judiciaire"}]},{"id":"soutien","kind":"finish","label":"Aide choisie et réévaluation régulière","detail":"<ul><li>Soutenir les décisions et l’autonomie avec les dispositifs adaptés.</li></ul>","branches":[]},{"id":"judiciaire","kind":"finish","label":"Procédure et mesure proportionnée à la situation","detail":"<ul><li>Évaluation médicale et judiciaire ; sauvegarde, curatelle ou tutelle selon besoin.</li><li>Maintenir participation, droits et réévaluation de la mesure.</li></ul>","branches":[]}]},"cards":[{"i":"329f5c437cae","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la différence de prise en charge médicale entre le handicap intellectuel et le handicap psychique ?","a":"<div class=\"notion-course\"><ul><li>Les deux nécessitent des soins somatiques et psychiques adaptés.</li><li>Le handicap intellectuel n’implique pas « peu de soins » ; les besoins dépendent des comorbidités et du fonctionnement.</li></ul></div>"},{"i":"691511aa3643","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Comment interpréter l’estimation de 700 000 personnes avec un handicap psychique citée dans le cours ?","a":"<div class=\"notion-course\"><ul><li>Ordre de grandeur historique, à ne pas présenter comme une prévalence nationale actuelle.</li><li>Retenir surtout la fréquence et le retentissement des troubles psychiatriques durables.</li></ul></div>"},{"i":"6c07d3ae0755","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la différence d'étiologie entre le handicap intellectuel et le handicap psychique ?","a":"<div class=\"notion-course\"><ul><li>Intellectuel : limitations intellectuelles et adaptatives durant le développement.</li><li>Psychique : conséquences fonctionnelles d’un trouble psychiatrique en interaction avec l’environnement.</li><li>Ils peuvent coexister.</li></ul></div>"},{"i":"ab8bacc8fd4f","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la différence d'apparition et d'évolution entre le handicap intellectuel et le handicap psychique ?","a":"<div class=\"notion-course\"><ul><li>Intellectuel : débute pendant le développement, pas nécessairement <span class=\"nc-pink_bg\">dès la naissance</span>.</li><li>Psychique : âge variable, souvent <span class=\"nc-pink nc-bold\">adolescence</span>/adulte ; retentissement souvent fluctuant.</li><li>Dans les deux cas, les capacités et besoins évoluent.</li></ul></div>"},{"i":"c4038ecf5842","n":121,"o":"121-1","u":"Définition","t":"Connaître la définition du handicap psychique, connaître la différence avec le handicap intellectuel","q":"Quelle est la définition du handicap psychique ?","a":"<div class=\"notion-course\"><ul><li>Limitations d’activité et restrictions de participation liées à un trouble psychiatrique, en interaction avec l’environnement.</li><li>Ne se réduit ni au diagnostic ni aux déficits cognitifs.</li></ul></div>"},{"i":"981d9b5f1381","n":121,"o":"121-2","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge","q":"Un patient stabilisé sur le plan délirant ne parvient pas à gérer repas et rendez-vous. Que faut-il évaluer ?","a":"<div class=\"notion-course\"><ul><li>Activités quotidiennes et participation, cognition, effets indésirables et environnement.</li><li>Projet partagé de soins et de compensation ; stabilisation symptomatique ≠ autonomie retrouvée.</li></ul></div>"},{"i":"7e4f42b75ff2","n":121,"o":"121-3","u":"Prise en charge","t":"Connaître les principes généraux de la prise en charge psychothérapeutique","q":"Quel préalable à une remédiation cognitive ?","a":"<div class=\"notion-course\"><ul><li>Évaluation individualisée des fonctions altérées et de leur retentissement.</li><li>Objectif concret choisi avec la personne et transfert dans la vie quotidienne.</li></ul></div>"},{"i":"21d2e1717d6b","n":121,"o":"121-4","u":"Prise en charge","t":"Connaître les principes de la réhabilitation psychosociale","q":"Une pension d’invalidité exclut-elle toujours une AAH ?","a":"<div class=\"notion-course\"><ul><li>Non : une AAH différentielle peut compléter une pension insuffisante sous conditions.</li></ul></div>"},{"i":"5248e8751850","n":121,"o":"121-4","u":"Prise en charge","t":"Connaître les principes de la réhabilitation psychosociale","q":"L’entreprise adaptée appartient-elle au milieu protégé ?","a":"<div class=\"notion-course\"><ul><li>Non : elle appartient au milieu ordinaire.</li><li>L’<span class=\"nc-pink nc-bold\">ESAT</span> est un établissement ou service médico-social ; orientation spécifique.</li></ul></div>"},{"i":"d214135fd812","n":121,"o":"121-5","u":"Prise en charge","t":"Connaître les principes de la prise en charge judiciaire","q":"Une schizophrénie justifie-t-elle automatiquement une tutelle ?","a":"<div class=\"notion-course\"><ul><li>Non : nécessité, subsidiarité et proportionnalité.</li><li>Évaluer les capacités, l’altération des facultés et les alternatives moins contraignantes.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181fab965de12d7387f1c?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddStatus":"Situations LiSA vérifiées le 14 octobre 2026 dans la session UNESS connectée.","algorithms":1,"lisaSituations":[{"number":269,"title":"Suivi et traitement de fond d’un trouble psychiatrique chronique hors dépression","url":"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_et_traitement_de_fond_d%27un_patient_souffrant_d%27un_trouble_psychiatrique_chronique_(hors_d%C3%A9pression)_SDD-269","expectations":["Réévaluer décompensation, risque suicidaire, comorbidités, autonomie et insertion ; surveiller les psychotropes et leur observance.","Expliquer les psychothérapies et coordonner les soins ; la valorisation du stage inclut réhabilitation, remédiation cognitive et démarches MDPH."],"verifiedAt":"2026-10-14"},{"number":345,"title":"Situation de handicap","url":"https://livret.uness.fr/lisa/2026/Situation_de_handicap_SDD-345","expectations":["Évaluer limitations d’activité, restrictions de participation, besoins de réadaptation et aides humaines ou matérielles.","Informer la personne et ses aidants, apprécier leur retentissement et orienter vers la MDPH ; intégrer les ressources du milieu de vie."],"verifiedAt":"2026-10-14"}]},"liensGlobaux":[{"href":"https://app.notion.com/p/1cb37f85d94181fab965de12d7387f1c?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024) ↗"},{"href":"https://www.ameli.fr/assure/droits-demarches/invalidite-handicap/handicap","label":"Assurance maladie · Invalidité et handicap, AAH différentielle ↗"},{"href":"https://www.service-public.fr/particuliers/vosdroits/R50473","label":"Service public · Protection juridique d’un majeur ↗"}]};
